insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-census-daily-schedule-s678','decision','The harvest gap census runs daily on main, so the Commons live counts never go a day stale','S678: the live counts went unread Nov 13 to 17 because harvest-gap-census.yml was dispatch-only and nobody dispatched it. It now also runs daily at 17:47 UTC on main (a schedule runs on the default branch, so the live-counts job runs), runs the spend builder first, and the failure watcher covers it (#3465).',array['commons','commons-data','live-counts','governance'],'proposed','S678 SkyWaxwing, #3465',null,null,'SkyWaxwing (S678)','2026-11-17'),
('d-cost-per-cre-weights-s678','decision','Cost per CRE: one outline row is 1 CRE, one program record is 15, fixed for Phase 1','Sam, 2026-11-17 (S678): 1 CRE = one course outline row (SLO or objective); one program record = 15 CRE; gaps noted count in full; cost per CRE = dollars spent / CREs collected over the same dates. Weights in kb/reference/cre_weights.json, fixed for Phase 1; new record types get their own weight. Baseline Fable Nov 11 to 14, ~21,500 CRE at ~$0.15 to $0.34.',array['commons','eta-clock','cost','cre'],'proposed','Sam, in session S678, 2026-11-17; kb/reference/cre_weights.json',null,null,'SkyWaxwing (S678)','2026-11-17'),
('f-cre-days-are-load-days-s678','fact','The CRE series counts rows by their last load day, so a reload re-dates them','S678: the live export''s by_day counts course_outcomes rows and program records by loaded_at day (records as HEAD counts, the table holds a person column). loaded_at is the latest load, so a reread re-dates rows; the 7-day cost per CRE reads loaded on, not first collected (Nov 11 to 17: ~19,537 CRE).',array['commons','eta-clock','cre','pitfall'],'proposed','S678 SkyWaxwing; kb/_commons_data_live.py',null,null,'SkyWaxwing (S678)','2026-11-17'),
('f-execute-sql-prompt-unreachable-s678','fact','The read-only SQL allow rule and guard are already live; the per-call prompt is the app mark','S678: Sam asked for a read-only SQL allow rule. Already present: the tracker''s .claude/settings.json and the session-root /home/user/.claude/settings.json allow execute_sql beside scripts/supabase_sql_guard.py (reads pass, writes denied); check_hooks_live.py reports LIVE. The prompt comes from the app''s per-call mark (2026-09-20). Route reads to the runner.',array['governance','supabase','permissions'],'proposed','S678 SkyWaxwing; scripts/check_hooks_live.py',null,null,'SkyWaxwing (S678)','2026-11-17'),
('d-left-map-link-only-decisions-s678','decision','Old titles that left MAP are kept, moved or removed by a link-only _LEFT_MAP:: decision','S678 (#3466): each old local title gets Keep, Move or Remove, stored as _LEFT_MAP::<raw> + left_map_decision; never an unclassified assignment, no remint, no retires.json; read live so it leaves the list the same day. A Move or combine mixing graded (CBE, Portfolio) with cert-based is blocked once, then logged. kb/_apply_left_map.py is not yet wired nightly.',array['exhibits','commons','left-map'],'proposed','Sam via COBIx #3464; S678 #3466',null,null,'SkyWaxwing (S678)','2026-11-17'),
('p-matcher-rules-need-self-recall-s678','pitfall','A new matcher rule waits on a held-out self-recall before it may move a card','S678: the second reader held #3467: on 134 person-decided cards, held out, rule D fired on 0 and W on 1, yet they moved 116 and 393 live cards; follow past rulings was built from the same cards. W and D are held by default; precedent is leave-one-out. #3468''s typographic rule waits on its first fill''s self-recall line.',array['courses','common-cr','second-reader','matcher'],'proposed','S678 second readers on #3467 and #3468',null,null,'SkyWaxwing (S678)','2026-11-17'),
('f-sparse-worktrees-for-workers-s678','fact','Parallel workers need sparse worktrees: 1.4 GB without receipts and the row audit, 4.8 GB full','S678: five full worktrees (4.8 GB each, 2.4 GB of it kb/receipts and 1.1 GB kb/row_audit) filled the disk. Sparse worktrees leaving out kb/receipts and kb/row_audit are 1.4 GB. Sam: keep to three workers at a time. The open-asks check reads STALE in a sparse tree and passes in CI.',array['governance','workers','disk'],'proposed','S678 SkyWaxwing; Sam in session',null,null,'SkyWaxwing (S678)','2026-11-17')
on conflict (slug) do nothing;

insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyWaxwing (S678)', 'create', 'S678 (2026-11-17)', to_jsonb(m)
from public.cpl_memory m where m.slug in ('d-census-daily-schedule-s678','d-cost-per-cre-weights-s678','f-cre-days-are-load-days-s678','f-execute-sql-prompt-unreachable-s678','d-left-map-link-only-decisions-s678','p-matcher-rules-need-self-recall-s678','f-sparse-worktrees-for-workers-s678')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');

select slug, kind, status, length(summary) as summary_len from public.cpl_memory
where slug in ('d-census-daily-schedule-s678','d-cost-per-cre-weights-s678','f-cre-days-are-load-days-s678','f-execute-sql-prompt-unreachable-s678','d-left-map-link-only-decisions-s678','p-matcher-rules-need-self-recall-s678','f-sparse-worktrees-for-workers-s678') order by slug;
